%[text] ## Introduction
%[text] Thermodynamics is commonly regarded as a science of equilibrium states. This perception arises because its classical formulation primarily describes thermodynamic properties and their relationships without explicitly incorporating time as an independent variable. Although this approach is fundamental to understanding thermodynamic systems, it may also lead to a misconception: that thermodynamics is inherently static, rather than a discipline capable of describing processes and energy transformations occurring over time.
%[text] In engineering applications, however, thermodynamic systems are rarely static. They undergo continuous transformations involving changes in volume, pressure, and temperature, while exchanging energy with their surroundings. These processes are inherently dynamic, and their behavior can be better understood when time is explicitly incorporated into their mathematical representation.
%[text] This work explores this perspective through a time-dependent simulation of the Carnot cycle, in which the volume of a gas is explicitly defined as a function of time, ($V=f(t)$). Rather than representing the cycle exclusively as a closed path in a pressure-volume diagram, the simulation incorporates the temporal evolution of the system through its four thermodynamic processes. By tracking the work transferred during each cycle, the resulting representation reveals the cumulative energy output (or input) as a function of time, providing a dynamic perspective on a classical thermodynamic model.
%%
%[text] ## Scenario Statement
%[text] ### Carnot Cycle
%[text] For this exercise it is considered 0.01 moles of an ideal gas which follow the properties $C\_v=(3/2)R$ and $C\_p=(5/2)R$, hence $\\gamma=C\_p/C\_v=5/3$. Gas is confined in a cylinder with variable volume moving a piston. As follows, the process is described both graphically and textually.
%[text] 
%[text]{"align":"center"} ![](text:image:8788)
%[text]{"align":"center"} 
% Physical Constants
R=8.314; % J/(mol*K)
Cv=3/2; %* R;     % J/(mol·K)
Cp=5/2; %* R;     % J/(mol·K)
gamma = 5/3; % Cp/Cv
n=0.01; % gas moles
%[text] The gas is subjected to the Carnot Cycle as follows;
%[text] 1. The process starts at atmospheric pressure (1 atm) $P\_1$, and volume $V\_1$.  Volumes are in Liters and Pressures in kPa. \
P1=101.325; % kPa
fprintf('P1 = %.2f kPa\n', P1); %[output:76704046]
V1=0.5; %[control:spinner:2809]{"position":[4,7]}
%[text] Temperature (Kelvin) is
%[text] $T\_H=\\frac{P\_1V\_1}{nR}$
TH=P1*V1/(n*R);
fprintf('T = %.2f K\n', TH); %[output:49e103ae]
%[text] 2\. The process has an isothermal expansion to $V\_2$.
V2=1.5; %[control:spinner:7b56]{"position":[4,7]}
if V2<=V1
    error('V2 must be greater than V1')
end
%[text] Expansion follows the trajectory
%[text] $P=P\_1\\frac{V\_1}{V}$
%[text] Pressure at $V\_2$ is
P2=P1*V1/V2;
fprintf('P2 = %.2f kPa\n',P2); %[output:8bfedb66]
%[text] 3\. Gas has an adiabatic expansion to $V\_3$.
V3=2.5; %[control:spinner:5424]{"position":[4,7]}
%[text] Expansion follows the trajectory
%[text] $P=P\_2\\left(\\frac{V\_2}{V}\\right)^\\gamma$
%[text] Pressure at $V\_3$ is
P3=P2*(V2/V3)^gamma;
fprintf('P3 = %.2f kPa\n',P3); %[output:8c0873fa]
%[text] 4\. Gas has an isothermal compression to $V\_4$ and after that returns adiabatically to $V\_1$, hence, $V\_4$ is determined by the intersection of curves
%[text] $P\_3\\frac{V\_3}{V\_4}=P\_\_1\\left(\\frac{V\_1}{V\_4}\\right)^\\gamma$
V4 = (P1*V1^gamma/(P3*V3))^(1/(gamma-1));
fprintf('V4 = %.2f L\n', V4); %[output:0c27644e]
P4 = P3*V3/V4;
fprintf('P4 = %.2f kPa\n', P4); %[output:941f8ef7]
%[text] Temperature at isothermal compression
TC=P3*V3/(n*R);
fprintf('T = %.2f K\n', TC); %[output:818f6416]
%%\ As follows pressure vs. volume in the Carnot cycle is defined
function P = Pfun(V,V1,V2,V3,P1,gamma)

P2 = P1*V1/V2;
P3 = P2*(V2/V3)^gamma;
V4 = (P1*V1^gamma/(P3*V3))^(1/(gamma-1));
P4 = P3*V3/V4;

P = NaN(size(V));

increasing = gradient(V) > 0;

i = V >= V1 & V < V2 & increasing;
P(i) = P1*V1./V(i);

i = V >= V2 & V < V3 & increasing;
P(i) = P2*(V2./V(i)).^gamma;

i = V <= V3 & V > V4 & ~increasing;
P(i) = P3*V3./V(i);

i = V <= V4 & V > V1 & ~increasing;
P(i) = P4*(V4./V(i)).^gamma;

P = fillmissing(P,'nearest');

end
%[text] ### Volume Dynamics
%[text] Volume oscillates between $V\_1$ and $V\_3$ according to 
%[text] $V=\\frac{V\_1+V\_3}{2}-\\frac{V\_3-V\_1}{2}\\cos\\left(\\frac{2\\pi N}{t\_f}t\\right)$
%[text] being $t$ the time in seconds, $t\_f$ the final time, and *N* the number of complete Carnot cycles.
tf=30;N=3; %[control:slider:7076]{"position":[4,6]} %[control:slider:39fc]{"position":[9,10]}

% Define the time-dependent volume
t = linspace(0,tf,100*N+1);
V = (V1 + V3)/2 - ((V3 - V1)/2)*cos(2*pi*N*t/tf);
P = Pfun(V,V1,V2,V3,P1,gamma);

% Figures
figure('Units','pixels','Position',[100 100 1800 400]) %[output:2dadf85e]
subplot(1,3,1) %[output:2dadf85e]
plot(t,V,'LineWidth',1.5) %[output:2dadf85e]
xlabel('Time (s)') %[output:2dadf85e]
ylabel('Volume (L)') %[output:2dadf85e]
title('Dynamics of Volume') %[output:2dadf85e]
grid on %[output:2dadf85e]

% Mark characteristic volumes according to the direction of motion
theta2 = acos(((V1 + V3)/2 - V2)/((V3 - V1)/2));
theta4 = acos(((V1 + V3)/2 - V4)/((V3 - V1)/2));

k = 0:N-1;
tV1 = tf*k/N;
tV2 = tf*(theta2 + 2*pi*k)/(2*pi*N);
tV3 = tf*(pi + 2*pi*k)/(2*pi*N);
tV4 = tf*(2*pi - theta4 + 2*pi*k)/(2*pi*N);

hold on %[output:2dadf85e]
plot(tV1,V1*ones(size(tV1)),'ko','MarkerFaceColor','r','HandleVisibility','off') %[output:2dadf85e]
plot(tV2,V2*ones(size(tV2)),'ko','MarkerFaceColor','g','HandleVisibility','off') %[output:2dadf85e]
plot(tV3,V3*ones(size(tV3)),'ko','MarkerFaceColor','b','HandleVisibility','off') %[output:2dadf85e]
plot(tV4,V4*ones(size(tV4)),'ko','MarkerFaceColor','m','HandleVisibility','off') %[output:2dadf85e]
hold off %[output:2dadf85e]

subplot(1,3,2) %[output:2dadf85e]
plot(t,P,'LineWidth',1.5) %[output:2dadf85e]
xlabel('Time (s)') %[output:2dadf85e]
ylabel('Pressure (kPa)') %[output:2dadf85e]
title('Dynamics of Pressure') %[output:2dadf85e]
grid on %[output:2dadf85e]
hold on %[output:2dadf85e]
plot(tV1,P1*ones(size(tV1)),'ko','MarkerFaceColor','r','HandleVisibility','off') %[output:2dadf85e]
plot(tV2,P2*ones(size(tV2)),'ko','MarkerFaceColor','g','HandleVisibility','off') %[output:2dadf85e]
plot(tV3,P3*ones(size(tV3)),'ko','MarkerFaceColor','b','HandleVisibility','off') %[output:2dadf85e]
plot(tV4,P4*ones(size(tV4)),'ko','MarkerFaceColor','m','HandleVisibility','off') %[output:2dadf85e]
hold off %[output:2dadf85e]

subplot(1,3,3) %[output:2dadf85e]

plot(V1,P1,'ko','MarkerFaceColor','r','HandleVisibility','off') %[output:2dadf85e]
hold on %[output:2dadf85e]
plot(V2,P2,'ko','MarkerFaceColor','g','HandleVisibility','off') %[output:2dadf85e]
plot(V3,P3,'ko','MarkerFaceColor','b','HandleVisibility','off') %[output:2dadf85e]
plot(V4,P4,'ko','MarkerFaceColor','m','HandleVisibility','off') %[output:2dadf85e]

title('PV chart') %[output:2dadf85e]
yLim = ylim;
xLim = xlim;
xlabel('Volume (L)') %[output:2dadf85e]
ylabel('Pressure (kPa)') %[output:2dadf85e]

xIso = linspace(1e-3, 4, 500);
auxTemps = [TC; TH]*(0.5:0.5:1.5);
auxTemps=auxTemps(:);

for T = auxTemps
    plot(xIso, n*R*T./xIso, '-', 'Color', [0.75 0.75 0.75], ... %[output:2dadf85e]
        'HandleVisibility', 'off'); %[output:2dadf85e]
end

ylim(yLim) %[output:2dadf85e]
xlim([xLim(1)-0.25 xLim(2)+0.25]) %[output:2dadf85e]

plot(V,P,'LineWidth',1.5) %[output:2dadf85e]

hold off %[output:2dadf85e]
%[text] The first two figures show the oscillatory dynamics of volume and pressure over the time. PV Chart eliminates the time, and this is how the cycle commonly presented. Points represent transitions between subprocesses.  
%[text] 
%%
%[text] ## Simulation of Work
%[text] Work obtained is the useful result of an engine. For PV process, it is defined as 
%[text] $W=\\oint\_CP\\,\\mathrm{d}V$
%[text] being *W* en Joules, and *C* the trajectory throughout of the Carnot Cycle. Here, the convention it that work in expansion is positive. Given the oscillatory behavior of the volume, the differential of volume is
%[text] $\\mathrm{d}V=\\left(\\frac{V\_3-V\_1}{2}\\right)\\left(\\frac{2\\pi N}{t\_f}\\right)\\sin\\left(\\frac{2\\pi N}{t\_f}t\\right)\\mathrm{d}t$
%[text] Hence, work can be calculated throughout cycles by
%[text] $W=\\left(\\frac{V\_3-V\_1}{2}\\right)\\left(\\frac{2\\pi N}{t\_f}\\right)\\int\_0^{t\_f}P(t)\\sin\\left(\\frac{2\\pi N}{t\_f}t\\right)\\mathrm{d}t$
%[text] The integral can be solved by a numerical method. Here, [`cumtrapz`](https://la.mathworks.com/help/releases/R2026b/matlab/ref/cumtrapz.html) command of MATLAB is used. 
PdV=P.*sin(2*pi*N*t/tf);
W = ((V3 - V1)/2)*(2*pi*N/tf)*cumtrapz(t,PdV);

% WH=n*R*TH*log(V2/V1);

figure %[output:35f4d975]
plot(t,W,'LineWidth',1.5) %[output:35f4d975]
hold on %[output:35f4d975]
tV = {tV1, tV2, tV3, tV4};
VLabels = {'V_1','V_2','V_3','V_4'};
colors = {'r','g','b','m'};

for j = 1:numel(tV)
    plot(tV{j},interp1(t,W,tV{j}),'ko', ... %[output:35f4d975]
        'MarkerFaceColor',colors{j}, ... %[output:35f4d975]
        'DisplayName',VLabels{j}); %[output:35f4d975]
end

% yline(WH,'LineStyle','--')

xlabel('Time (s)') %[output:35f4d975]
ylabel('Cumulative Work Output (J)') %[output:35f4d975]
title('Work during the Carnot cycles') %[output:35f4d975]

legend('Work',VLabels{:},'Location','best') %[output:35f4d975]
grid on %[output:35f4d975]
hold off %[output:35f4d975]
%[text] Finally efficiency of the cycle is calculated by
%[text] $Efficiency=1-\\frac{T\_C}{T\_H}$
Efficiency=1-TC/TH %[output:2b45668b]
